#include <stdio.h>
#include <string.h>
void revStr(char*s) {
    int l=0, r=strlen(s)-1;
    while (l<r) {
        char t=s[l];
        s[l++]=s[r];
        s[r--]=t;
    }
}
int main() {
    char s[]="hello";
    revStr(s);
    printf("%s\n", s);
    return 0;
}

